using namespace std;
inline char getc()
{ 
    static char buf[1<<18],*p1=buf,*p2=buf; 
    return p1==p2&&(p2=(p1=buf)+fread(buf,1,1<<18,stdin),p1==p2)?EOF:*p1++; 
} 
inline int read()
{ 
    char ch=getc();
    int sum=0,f=1; 
    while(!isdigit(ch)) {
        if(ch=='-') f=-1;
        ch=getc();
    }
    while(isdigit(ch))
    {
        sum=(sum<<1)+(sum<<3)+(ch^48);
        ch=getc();
    }
    return sum*f; 
}
int main()
{
    int t;
    t=read();
    while(t--) {
        int n,m,k;
        n=read();m=read();k=read();
        int i;
        int a[n];
        for(i=0;i<n;i++) a[i]=read();
        for(i=0;i<n-1;i++)
        {
            if(a[i+1]-a[i]>k) {
                if(a[i+1]-a[i]-k<=m) m-=a[i+1]-a[i]-k;
                else break;
            }
            else m+=min(a[i]+k-a[i+1],a[i]);
        }
        if(i==n-1) printf("YES\n");
        else printf("NO\n");
    }
    return 0;
}

#include <bits/stdc++.h>
using namespace std;
int n, m, a[200010];
double ans;
inline int read()
{
	int x = 0, f = 1; char ch = getchar();
	while (ch < '0' || ch > '9') { if (ch == '-') f = -1; ch = getchar(); }
	while (ch >= '0' && ch <= '9') { x = x * 10 + ch - '0'; ch = getchar(); }
	return x * f;
}
int main()
{
	n = read();
	m = read();
	for(int i = 1; i <= n; i ++)
		a[i] = read();
	double now = 0;
	for(int j = 1; j <= m; j ++)
		now += a[j];
	ans += (double) now;
	for(int j = m + 1; j <= n; j ++)
	{
		now += a[j];
		now -= a[j - m];
		ans += now;
	}
	printf("%.10lf",(double) ans / (n - m + 1));

	return 0;
}

